/**
 * 3D 中国象棋 - 完整游戏版本
 * 集成象棋引擎和完整游戏逻辑
 */

import { useState, useCallback, useEffect } from 'react';
import { ChessBoard3D, ThemeSelector } from './components/ChessBoard3D';
import { GameUI } from './components/GameUI';
import { themes, defaultTheme } from './themes';
import {
  createInitialGameState,
  makeMove,
  getValidMoves,
  GameState,
  Position,
  Piece,
} from './game/chess-engine';

function App() {
  const [currentTheme, setCurrentTheme] = useState('mingqing');
  const [gameState, setGameState] = useState<GameState>(createInitialGameState());
  const [selectedPiece, setSelectedPiece] = useState<string | null>(null);
  const [validMoves, setValidMoves] = useState<Position[]>([]);
  const [timer, setTimer] = useState({ red: 600, black: 600 }); // 10 分钟

  const theme = themes[currentTheme] || defaultTheme;

  // 计时器
  useEffect(() => {
    const interval = setInterval(() => {
      setTimer(prev => ({
        ...prev,
        [gameState.currentPlayer]: Math.max(0, prev[gameState.currentPlayer] - 1),
      }));
    }, 1000);
    return () => clearInterval(interval);
  }, [gameState.currentPlayer]);

  const handlePieceClick = useCallback((pieceId: string) => {
    const piece = gameState.board.flat().find(p => p?.id === pieceId);
    if (!piece) return;

    // 如果点击的是己方棋子
    if (piece.color === gameState.currentPlayer) {
      setSelectedPiece(pieceId);
      const moves = getValidMoves(gameState.board, piece);
      setValidMoves(moves);
    } 
    // 如果点击的是敌方棋子且已选中己方棋子
    else if (selectedPiece) {
      const selectedPieceObj = gameState.board.flat().find(p => p?.id === selectedPiece);
      if (selectedPieceObj) {
        const from = selectedPieceObj.position;
        const to = piece.position;
        handleMove(from, to);
      }
    }
  }, [gameState, selectedPiece]);

  const handleSquareClick = useCallback((x: number, y: number) => {
    if (selectedPiece) {
      const selectedPieceObj = gameState.board.flat().find(p => p?.id === selectedPiece);
      if (selectedPieceObj) {
        const from = selectedPieceObj.position;
        const to = { x, y };

        // 检查是否是有效移动
        const isValid = validMoves.some(m => m.x === x && m.y === y);
        if (isValid) {
          handleMove(from, to);
        } else {
          // 点击空白处取消选择
          setSelectedPiece(null);
          setValidMoves([]);
        }
      }
    }
  }, [selectedPiece, gameState, validMoves]);

  const handleMove = useCallback((from: Position, to: Position) => {
    const result = makeMove(gameState, from, to);
    if (result.success && result.gameState) {
      setGameState(result.gameState);
      setSelectedPiece(null);
      setValidMoves([]);
    } else {
      console.error('移动失败:', result.error);
    }
  }, [gameState]);

  const handleUndo = useCallback(() => {
    // TODO: 实现悔棋功能
    console.log('悔棋');
  }, []);

  const handleReset = useCallback(() => {
    setGameState(createInitialGameState());
    setSelectedPiece(null);
    setValidMoves([]);
    setTimer({ red: 600, black: 600 });
  }, []);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  // 转换棋盘为组件需要的格式
  const pieces = gameState.board.flatMap((row, y) =>
    row.map((piece, x) => piece ? ({
      id: piece.id,
      type: piece.type === 'king' ? (piece.color === 'red' ? '帥' : '將') :
            piece.type === 'advisor' ? (piece.color === 'red' ? '仕' : '士') :
            piece.type === 'elephant' ? (piece.color === 'red' ? '相' : '象') :
            piece.type === 'horse' ? '馬' :
            piece.type === 'rook' ? '車' :
            piece.type === 'cannon' ? '炮' :
            (piece.color === 'red' ? '兵' : '卒'),
      isRed: piece.color === 'red',
      position: [x - 4, 0.2, (y - 4.5) * -1] as [number, number, number],
    }) : null).filter(Boolean)
  ) as Array<{ id: string; type: string; isRed: boolean; position: [number, number, number] }>;

  return (
    <div 
      className="w-screen h-screen flex overflow-hidden"
      style={{ background: theme.colors.background }}
    >
      {/* 左侧：3D 棋盘 */}
      <div className="flex-1 h-full relative">
        <ChessBoard3D
          themeId={currentTheme}
          pieces={pieces}
          selectedPiece={selectedPiece}
          highlightedPositions={validMoves.map(m => [m.x - 4, (m.y - 4.5) * -1] as [number, number])}
          onPieceClick={handlePieceClick}
          onSquareClick={handleSquareClick}
        />

        {/* 主题选择器浮层 */}
        <div className="absolute top-4 left-4 z-10">
          <ThemeSelector
            currentTheme={currentTheme}
            onThemeChange={setCurrentTheme}
          />
        </div>

        {/* 游戏状态提示 */}
        {gameState.status === 'check' && (
          <div 
            className="absolute top-20 left-4 px-4 py-2 rounded-lg text-lg font-bold animate-pulse"
            style={{
              background: theme.colors.accent,
              color: '#FFF',
            }}
          >
            将军！
          </div>
        )}

        {gameState.status === 'checkmate' && (
          <div 
            className="absolute top-20 left-4 px-4 py-2 rounded-lg text-lg font-bold"
            style={{
              background: theme.colors.accent,
              color: '#FFF',
            }}
          >
            将死！{gameState.winner === 'red' ? '红方' : '黑方'}获胜！
          </div>
        )}

        {/* 版本信息 */}
        <div 
          className="absolute bottom-4 left-4 px-3 py-2 rounded text-sm"
          style={{
            background: theme.ui.panelBg,
            color: theme.colors.textMuted,
            border: `1px solid ${theme.ui.panelBorder}`,
          }}
        >
          3D 中国象棋 v2.0 | {theme.name} | {gameState.status === 'playing' ? '进行中' : gameState.status === 'check' ? '将军' : gameState.status === 'checkmate' ? '将死' : '和棋'}
        </div>
      </div>

      {/* 右侧：游戏 UI */}
      <div className="w-80 h-full border-l" style={{ borderColor: theme.ui.panelBorder }}>
        <GameUI
          themeId={currentTheme}
          onThemeChange={setCurrentTheme}
          currentPlayer={gameState.currentPlayer}
          moveHistory={gameState.moveHistory.map(m => m.notation || '')}
          capturedPieces={{
            red: gameState.capturedPieces.red.map(p => 
              p.type === 'king' ? '将' :
              p.type === 'advisor' ? '士' :
              p.type === 'elephant' ? '象' :
              p.type === 'horse' ? '马' :
              p.type === 'rook' ? '车' :
              p.type === 'cannon' ? '炮' : '卒'
            ),
            black: gameState.capturedPieces.black.map(p => 
              p.type === 'king' ? '帅' :
              p.type === 'advisor' ? '仕' :
              p.type === 'elephant' ? '相' :
              p.type === 'horse' ? '马' :
              p.type === 'rook' ? '车' :
              p.type === 'cannon' ? '炮' : '兵'
            ),
          }}
          timer={{ red: timer.red, black: timer.black }}
          onUndo={handleUndo}
          onReset={handleReset}
        />
      </div>
    </div>
  );
}

export default App;

